import streamlit as st
import openpyxl
from openpyxl.styles import PatternFill
import io
import re
import copy
import base64

# ─────────────────────────────────────────────
# 組み込みベースExcel（25-26シーズン　旭川総体）
# ─────────────────────────────────────────────
BUILTIN_EXCEL_B64 = """"""
BUILTIN_EXCEL_NAME = "25-26シーズン　旭川総体"
BUILTIN_EXCEL2_B64  = """"""
BUILTIN_EXCEL2_NAME = "26-27シーズン　旭川総体（オーナーズシート）"


st.set_page_config(page_title="座席マップ 青塗りツール", layout="wide")
st.title("🏟️ 座席マップ 青塗りツール")
st.caption("クラス名＋列＋座席番号を入力し、座席シートのセルを青色に塗りつぶします")

# ─────────────────────────────────────────────
# 1. パース関数
# ─────────────────────────────────────────────
def parse_seat_text(text):
    """
    テキストから (class_name, row_num, seat_num) のリストを返す
    例:
      Class S South 1列33
      Class SS End-1 2列　8、9
      Class A Side 3列8,9
    """
    results = []

    # 改行 or 「Class」の前で分割
    # まず全行を「Class」で分割して各エントリを処理
    # 全角スペース→半角
    text = text.replace('\u3000', ' ').replace('　', ' ')

    # Classで始まるブロックに分割
    blocks = re.split(r'(?=Class\s)', text)

    for block in blocks:
        block = block.strip()
        if not block:
            continue

        # クラス名パターン: Class SS-T / Class SS End-1 / Class S South / Class A Side など
        # 列パターン: 数字 + 列
        # 座席パターン: 数字（複数は "、" "," "." で区切り or "25.26" のような形）
        m = re.match(
            r'(Class\s+\S+(?:\s+\S+)?)\s+(\d+)列\s*([\d\s、,．.・]+)',
            block
        )
        if not m:
            # クラス名が3トークンのパターン試行: Class A End-1 など
            m = re.match(
                r'(Class\s+\S+\s+\S+)\s+(\d+)列\s*([\d\s、,．.・]+)',
                block
            )
        if not m:
            continue

        class_name = m.group(1).strip()
        row_num = int(m.group(2))
        seat_str = m.group(3)

        # 座席番号を展開 (区切り文字: 、, ．.)
        seat_parts = re.split(r'[、,．.\s・]+', seat_str.strip())
        for sp in seat_parts:
            sp = sp.strip()
            if sp.isdigit():
                results.append((class_name, row_num, int(sp)))

    # 重複排除
    return list(set(results))


def normalize_class(s):
    """スペース・ハイフンを統一して比較用に正規化（25-26/26-27 両対応）"""
    s = re.sub(r'\s+', ' ', str(s).strip())
    # ハイフンをスペースに統一して比較（Class S-Side → Class S Side）
    s = s.replace('-', ' ')
    # 連続スペースを再度整理
    s = re.sub(r'\s+', ' ', s)
    return s


# ─────────────────────────────────────────────
# 2. UI
# ─────────────────────────────────────────────
import datetime

col1, col2 = st.columns([1, 2])

with col1:
    # ── ベースExcel選択 ──
    excel_choice = st.radio(
        "📂 ベースExcelを選択",
        options=[
            BUILTIN_EXCEL_NAME,
            BUILTIN_EXCEL2_NAME,
            "ファイルをアップロード",
        ],
        help="よく使うファイルはそのまま使用できます"
    )

    uploaded = None
    if excel_choice == "ファイルをアップロード":
        uploaded = st.file_uploader(
            "Excelファイルを選択",
            type=["xlsx"],
            help="座席番号 / 列 / クラス シートを含むファイル"
        )
        excel_ready = uploaded is not None
    else:
        st.success(f"✅ **{excel_choice}**")
        excel_ready = True

    game_date = st.date_input(
        "📅 試合日付",
        value=datetime.date.today(),
        help="シート名・ファイル名に使用されます（例：1月1日 → 0101）"
    )
    date_str = game_date.strftime("%m%d")
    st.caption(f"シート名・ファイル名に使用される日付コード：**{date_str}**")

with col2:
    seat_text = st.text_area(
        "📝 座席指定テキストを貼り付け",
        height=200,
        placeholder="例:\nClass S South 1列33\nClass S South 1列5\nClass SS End-1 2列8、9"
    )

run = st.button("🎨 青塗り実行", type="primary", disabled=(not excel_ready or not seat_text.strip()))

# ─────────────────────────────────────────────
# 3. 処理
# ─────────────────────────────────────────────
if run:
    with st.spinner("処理中..."):
        # パース
        seats = parse_seat_text(seat_text)
        if not seats:
            st.error("座席指定を解析できませんでした。入力形式を確認してください。")
            st.stop()

        st.write(f"**解析された座席数:** {len(seats)} 件")

        # Excelロード（組み込み1 / 組み込み2 / アップロード）
        if excel_choice == "ファイルをアップロード":
            excel_bytes = io.BytesIO(uploaded.read())
            source_name = uploaded.name.replace(".xlsx", "")
        elif excel_choice == BUILTIN_EXCEL2_NAME:
            excel_bytes = io.BytesIO(base64.b64decode(BUILTIN_EXCEL2_B64))
            source_name = BUILTIN_EXCEL2_NAME
        else:
            excel_bytes = io.BytesIO(base64.b64decode(BUILTIN_EXCEL_B64))
            source_name = BUILTIN_EXCEL_NAME
        wb = openpyxl.load_workbook(excel_bytes)

        # シート名を自動判別（25-26 / 26-27 両対応）
        # シート名を自動判別（25-26 / 26-27 両対応）
        # パターン: (座席番号, 列, クラス, オーナーズシート or None)
        SHEET_PATTERNS = [
            ('25－26ブロックマップ_座席番号', '25－26ブロックマップ_列', '25－26ブロックマップ_クラス', None),
            ('26-27ブロックマップ案_席番号',  '26-27ブロックマップ案_列', '26-27ブロックマップ案_クラス', '26-27ブロックマップ案_オーナーズシート'),
        ]
        matched_pattern = None
        for pattern in SHEET_PATTERNS:
            if all(s in wb.sheetnames for s in pattern[:3]):
                matched_pattern = pattern
                break
        if matched_pattern is None:
            st.error(f"対応するシートが見つかりません。シート一覧: {wb.sheetnames}")
            st.stop()

        ws_seat   = wb[matched_pattern[0]]
        ws_row    = wb[matched_pattern[1]]
        ws_class  = wb[matched_pattern[2]]
        ws_owner  = wb[matched_pattern[3]] if matched_pattern[3] else None
        is_2627   = ws_owner is not None

        # 26-27の場合：赤セルのみが対象。赤セル座標をセットとして保持
        if is_2627:
            red_coords = set()
            for row in ws_owner.iter_rows():
                for cell in row:
                    if cell.fill and cell.fill.fill_type == 'solid':
                        rgb = cell.fill.fgColor.rgb
                        try:
                            r = int(rgb[2:4], 16)
                            g = int(rgb[4:6], 16)
                            b = int(rgb[6:8], 16)
                            if r > 180 and g < 100 and b < 100:
                                red_coords.add((cell.row, cell.column))
                        except:
                            pass

        BLUE_FILL = PatternFill("solid", fgColor="0000FF")

        # セル座標マップ構築: (class_name, row_val, seat_val) -> (r, c)
        # 全セルを走査してインデックス化
        coord_map = {}
        max_row = ws_class.max_row
        max_col = ws_class.max_column

        for r in range(1, max_row + 1):
            for c in range(1, max_col + 1):
                cv = ws_class.cell(row=r, column=c).value
                rv = ws_row.cell(row=r, column=c).value
                sv = ws_seat.cell(row=r, column=c).value

                if cv is None or rv is None or sv is None:
                    continue

                cv_norm = normalize_class(str(cv))
                try:
                    rv_int = int(rv)
                except (ValueError, TypeError):
                    continue
                try:
                    sv_int = int(sv)
                except (ValueError, TypeError):
                    continue

                coord_map[(cv_norm, rv_int, sv_int)] = (r, c)

        # 突合＆塗り
        matched   = []
        unmatched = []
        not_red   = []  # 26-27専用：赤色でなかった席

        for (class_name, row_num, seat_num) in seats:
            key = (normalize_class(class_name), row_num, seat_num)
            if key in coord_map:
                r, c = coord_map[key]
                if is_2627 and (r, c) not in red_coords:
                    # 赤色でないセルはエラー扱い
                    not_red.append({
                        "クラス": class_name,
                        "列": row_num,
                        "座席": seat_num,
                    })
                else:
                    ws_seat.cell(row=r, column=c).fill = BLUE_FILL
                    if is_2627:
                        ws_owner.cell(row=r, column=c).fill = BLUE_FILL
                    matched.append({
                        "クラス": class_name,
                        "列": row_num,
                        "座席": seat_num,
                        "セル": f"R{r}C{c}"
                    })
            else:
                unmatched.append({
                    "クラス": class_name,
                    "列": row_num,
                    "座席": seat_num
                })

        # 出力：セルを1つずつコピー（列幅を確実に指定通りに保つため）
        from openpyxl import Workbook
        from openpyxl.styles import PatternFill as PF, Font, Alignment
        from openpyxl.utils import column_index_from_string, get_column_letter
        from copy import copy as style_copy

        # 26-27はオーナーズシートをベースに出力
        ws_src = ws_owner if is_2627 else ws_seat
        wb_out = Workbook()
        wb_out.remove(wb_out.active)
        ws_dst = wb_out.create_sheet(date_str)

        # ── セルの値・スタイルをコピー（フォントキャッシュで高速化）──
        CENTER = Alignment(horizontal="center", vertical="center")
        FONT_CACHE = {}
        for row in ws_src.iter_rows():
            for cell in row:
                new_cell = ws_dst.cell(row=cell.row, column=cell.column, value=cell.value)
                # フォント（11pt固定・他属性は元のまま）
                orig = cell.font
                try:
                    rgb = orig.color.rgb if orig.color and orig.color.type == 'rgb' else None
                except Exception:
                    rgb = None
                key = (orig.name, orig.bold, orig.italic, rgb)
                if key not in FONT_CACHE:
                    FONT_CACHE[key] = Font(
                        name=orig.name or "Calibri", size=11,
                        bold=orig.bold, italic=orig.italic, color=orig.color,
                    )
                new_cell.font      = FONT_CACHE[key]
                new_cell.alignment = CENTER
                if cell.has_style:
                    new_cell.border        = style_copy(cell.border)
                    new_cell.fill          = style_copy(cell.fill)
                    new_cell.number_format = cell.number_format

        # ── X列(24列)行7-18の塗り・Y列(25列)行7-12の値をクリア（25-26のみ）──
        if not is_2627:
            for r in range(7, 19):
                ws_dst.cell(row=r, column=24).fill  = PF(fill_type=None)
                ws_dst.cell(row=r, column=24).value = None
            for r in range(7, 13):
                ws_dst.cell(row=r, column=25).value = None
                ws_dst.cell(row=r, column=25).fill  = PF(fill_type=None)

        # ── 結合セルをコピー ──
        for merge in ws_src.merged_cells.ranges:
            ws_dst.merge_cells(str(merge))

        # ── 列幅の設定（31px / 38px / 41px）──
        COL_41PX = 5.1429
        COL_38PX = 4.7143
        COL_31PX = 3.7143
        MAX_COL  = ws_src.max_column

        RANGES_31PX = [
            ("A", "M"), ("S", "Y"), ("AA", "AK"),
            ("CJ", "CS"), ("CU", "DC"), ("DI", get_column_letter(MAX_COL)),
        ]
        RANGES_38PX = [
            ("N", "Z"), ("AL", "CI"), ("CT", "CT"), ("DD", "DH"),
        ]

        def build_col_set(ranges):
            cols = set()
            for s, e in ranges:
                for i in range(column_index_from_string(s), column_index_from_string(e) + 1):
                    cols.add(i)
            return cols

        cols_31px = build_col_set(RANGES_31PX)
        cols_38px = build_col_set(RANGES_38PX)

        ws_dst.sheet_format.defaultColWidth  = COL_41PX
        ws_dst.sheet_format.defaultRowHeight = ws_src.sheet_format.defaultRowHeight
        ws_dst.sheet_format.customHeight     = ws_src.sheet_format.customHeight

        for i in range(1, MAX_COL + 1):
            col_letter = get_column_letter(i)
            if i in cols_31px:
                ws_dst.column_dimensions[col_letter].width = COL_31PX
            elif i in cols_38px:
                ws_dst.column_dimensions[col_letter].width = COL_38PX
            else:
                ws_dst.column_dimensions[col_letter].width = COL_41PX

        # ── 行高をコピー ──
        for row, rd in ws_src.row_dimensions.items():
            ws_dst.row_dimensions[row].height = rd.height


        out_buf = io.BytesIO()
        wb_out.save(out_buf)
        out_buf.seek(0)

        out_name = f"{source_name}_{date_str}_blue_marked.xlsx"

    # ─────────────────────────────────────────────
    # 4. 結果表示
    # ─────────────────────────────────────────────
    st.success(f"✅ 完了！ 塗り: {len(matched)}件 / 未一致: {len(unmatched)}件")

    col_a, col_b = st.columns(2)

    with col_a:
        st.subheader(f"✅ 塗れた席（{len(matched)}件）")
        if matched:
            st.dataframe(matched, use_container_width=True)
        else:
            st.info("一致なし")

    with col_b:
        st.subheader(f"❌ 塗れなかった席（{len(unmatched)}件）")
        if unmatched:
            st.dataframe(unmatched, use_container_width=True)
            st.caption("クラス名・列・座席番号がデータに存在しない可能性があります")
        else:
            st.success("すべての座席が一致しました！")

    if not_red:
        st.subheader(f"⚠️ オーナーズシート対象外の席（{len(not_red)}件）")
        st.dataframe(not_red, use_container_width=True)
        st.caption("オーナーズシートで赤色になっていない席のため、青塗りをスキップしました")

    st.download_button(
        label="⬇️ 出力Excelをダウンロード",
        data=out_buf,
        file_name=out_name,
        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        type="primary"
    )

# ─────────────────────────────────────────────
# サイドバー: ヘルプ
# ─────────────────────────────────────────────
with st.sidebar:
    st.header("📖 入力形式")
    st.markdown("""
**基本形式:**
```
クラス名 列数字列 座席番号
```

**使用例:**
```
Class S South 1列33
Class S South 1列5
Class SS End-1 2列8、9
Class A Side 3列8,9
```

**複数座席の区切り文字:**
- 読点: `8、9`
- カンマ: `8,9`
- スペース: `8 9`
- ピリオド: `25.26`

**利用可能なクラス名:**
- Class S South
- Class S Side
- Class S End-1 / End-2
- Class SS Side
- Class SS End-1 / End-2
- Class SS-T
- Class A South
- Class A Side
- Class A End-1 / End-2
- Class B Side
- Class B End-1 / End-2
""")
